#!/usr/bin/env python
import csv,json
from pathlib import Path
import matplotlib.pyplot as plt

O=Path('dual_branch_outputs/p8_diagnosis');P=Path('dual_branch_outputs/p7_downstream')
load=lambda p:json.loads(Path(p).read_text())
raw=load(P/'p7_raw_metrics.json');inter=load(O/'p8_interpolation_downstream.json');geom=load(O/'p8_interpolation_results.json')['representation'];proj=load(O/'p8_projector_diagnostics.json');bootc=load(O/'p8_bootstrap_caption.json');bootg=load(O/'p8_bootstrap_grounding.json');bootr=load(O/'p8_bootstrap_rsa.json');hard=load(O/'p8_hard_retrieval.json');audit=load(O/'p8_real_random_audit.json');sample=load(O/'p8_sample_level_analysis.json')
variants=('lora','full_real','full_random');p7name={'lora':'lora','full_real':'full_real','full_random':'full_random'};rows=[]
for v in variants:
 for a in (0,.25,.5,.75,1):
  if a==0:c=raw['caption_metrics']['umbrae'];g=raw['grounding_metrics']['umbrae']
  elif a==1:c=raw['caption_metrics'][p7name[v]];g=raw['grounding_metrics'][p7name[v]]
  else:c=next(x for x in inter['caption'] if x['variant']==v and x['alpha']==a);g=next(x for x in inter['grounding'] if x['variant']==v and x['alpha']==a)
  r=next(x for x in geom if x['variant']==v and x['alpha']==a)
  rows.append({'variant':v,'alpha':a,'RSA':r['brain_rsa']['spearman_rsa'],'variant_to_base_cosine':r['variant_to_base_cosine'],'feature_norm_ratio':r['feature_norm_ratio_to_base'],'CIDEr':c['CIDEr'],'BLEU-4':c['BLEU-4'],'ROUGE-L':c['ROUGE-L'],'Mean_IoU':g['mean_iou'],'Grounding_Accuracy':g['grounding_accuracy'],'parse_failures':g['parse_failures']})
for name,fields in [('caption',['variant','alpha','CIDEr','BLEU-4','ROUGE-L']),('grounding',['variant','alpha','Mean_IoU','Grounding_Accuracy','parse_failures']),('geometry_utility',list(rows[0]))]:
 with (O/f'p8_interpolation_{name}.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows([{k:x[k] for k in fields} for x in rows])
(O/'p8_geometry_utility.csv').write_text((O/'p8_interpolation_geometry_utility.csv').read_text())
colors={'lora':'C0','full_real':'C1','full_random':'C2'}
def plot(name,xkey,ykeys,xlabel):
 plt.figure(figsize=(6,4))
 for v in variants:
  q=[x for x in rows if x['variant']==v]
  for y in ykeys:plt.plot([x[xkey] for x in q],[x[y] for x in q],marker='o',label=f'{v} {y}')
 plt.xlabel(xlabel);plt.legend(fontsize=7);plt.tight_layout();plt.savefig(O/name,dpi=160);plt.close()
plot('rsa_vs_cider.png','RSA',['CIDEr'],'RSA');plot('rsa_vs_grounding_acc.png','RSA',['Grounding_Accuracy'],'RSA');plot('alpha_vs_cider.png','alpha',['CIDEr'],'alpha');plot('alpha_vs_rsa.png','alpha',['RSA'],'alpha');plot('alpha_vs_grounding.png','alpha',['Mean_IoU','Grounding_Accuracy'],'alpha')
