best=max(rows,key=lambda x:x['CIDEr']);summary={'P8_DIAGNOSIS':'OVER_CALIBRATION','CALIBRATION_DIRECTION':'PROMISING','CURRENT_CALIBRATION_STRENGTH':'TOO_STRONG','ANATOMICAL_SIGNAL':'DIRECTIONAL_ONLY','NEXT_STAGE':'P9_PRESERVATION_CONSTRAINED_CALIBRATION','P9_RECOMMENDATION':'A_STRONGER_PRESERVATION_PLUS_C_WEAKER_FUSION_AND_D_PROJECTOR_AWARE_PRESERVATION','sweet_spot':best,'projector_amplification':{v:proj['modes'][v]['amplification_ratio'] for v in variants},'projector_interface_mismatch':False,'geometry_survives_projector':True,'hard_retrieval':{m:{k:hard['models'][m][k] for k in ('recall_at_1','recall_at_5','recall_at_10','mrr','median_rank')} for m in ('umbrae',*variants)},'real_random_capacity_match':audit['REAL_RANDOM_CAPACITY_MATCH'],'random_control_limitation':audit['RANDOM_CONTROL_LIMITATION'],'bootstrap_caption_real_random':bootc['comparisons']['full_real_minus_full_random'],'bootstrap_grounding_real_random':bootg['comparisons']['full_real_minus_full_random'],'P8_STATUS':'COMPLETE','NEW_TRAINING_STARTED':False,'PARCEL_STAGE_STARTED':False,'PRF_STAGE_STARTED':False,'RETINOTOPY_STAGE_STARTED':False}
(O/'p8_summary.json').write_text(json.dumps(summary,indent=2)+'\n')
report=f'''# P8 Downstream-Compatible Structural Calibration Diagnosis\n\n## 1. Setup\nLocked test, 982 images and 2,419 grounding queries; frozen P7 checkpoints, mm_projector and Shikra. Alpha grid: 0, .25, .5, .75, 1.\n\n## 2. Statistical Validation\n10,000 paired caption, cluster-grounding and stimulus-RSA bootstraps. Real-Random CIs cross zero for all primary downstream metrics; anatomical evidence is directional only.\n\n## 3. Geometry–Utility Interpolation\nFull Real alpha=.25 is the CIDEr sweet spot: CIDEr {best['CIDEr']:.6f}, BLEU-4 {best['BLEU-4']:.6f}, grounding accuracy {best['Grounding_Accuracy']:.6f}, RSA {best['RSA']:.6f}. It improves alpha=1 and preserves/improves key baseline utilities. Diagnosis: over-calibration.\n\n## 4. Projector Interface Diagnostics\nAmplification ratios are {summary['projector_amplification']}. RSA gains persist after projection; no strong decoder-interface amplification evidence.\n\n## 5. Hard Retrieval\nK=99 hard negatives remove R@1 saturation. Full models improve median rank from 8 to 7; Real and Random remain close.\n\n## 6. Real vs Random Evidence\nArchitectural capacity and group sizes match, but checkpoint epochs differ and only one random seed exists. REAL_RANDOM_CAPACITY_MATCH = FAIL.\n\n## 7. Sample-Level Analysis\nCaption and grounding paired wins/ties plus baseline-difficulty and target-size groups are in p8_sample_level_analysis.json.\n\n## 8. Failure / Success Cases\nFixed P7 sample IDs 0-9 are retained without reselection. Alpha endpoints have zero max absolute error. Failures remain in metric denominators.\n\n## 9. Scientific Interpretation\nH1 is supported: a weaker residual strength improves utility while retaining geometry gains. H2 is not strongly supported. Anatomy remains directional only.\n\n## 10. Decision for P9\nP8_DIAGNOSIS = OVER_CALIBRATION\nNEXT_STAGE = P9_PRESERVATION_CONSTRAINED_CALIBRATION\nP9 should prioritize stronger/projector-aware preservation and weaker fusion; do not proceed to parcel/pRF yet.\n\nP8_STATUS = COMPLETE\nNEW_TRAINING_STARTED = false\nPARCEL_STAGE_STARTED = false\nPRF_STAGE_STARTED = false\nRETINOTOPY_STAGE_STARTED = false\nP9_RECOMMENDATION = {summary['P9_RECOMMENDATION']}\n''';(O/'p8_report.md').write_text(report)
print(json.dumps(summary,indent=2))
